old="host.insertBefore(b,host.firstChild)"
new="const ov=document.getElementById('fiOv');if(ov){ov.appendChild(b)}else{host.insertBefore(b,host.firstChild)}"
print('k3 replaced',old in s); s=s.replace(old,new); open(f,'w',encoding='utf-8').write(s)
